from reportlab.pdfgen import canvas
from reportlab.platypus import Paragraph, Frame
from reportlab.lib.styles import ParagraphStyle
from reportlab.lib import colors
from xml.sax.saxutils import escape
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
pdfmetrics.registerFont(TTFont("Arial", "/System/Library/Fonts/Supplemental/Arial.ttf"))
pdfmetrics.registerFont(TTFont("Arial-Bold", "/System/Library/Fonts/Supplemental/Arial Bold.ttf"))
OUT='output/pdf/yourday-privacy-policy-en.pdf'
W,H=595.28,841.89
c=canvas.Canvas(OUT,pagesize=(W,H));c.setTitle('yourday Privacy Policy');c.setAuthor('Smile Dragon')
styles={
'body':ParagraphStyle('body',fontName='Arial',fontSize=10.5,leading=15.5,spaceAfter=10,textColor=colors.HexColor('#283738')),
'h':ParagraphStyle('h',fontName='Arial-Bold',fontSize=12,leading=17,spaceBefore=12,spaceAfter=8,textColor=colors.HexColor('#155E63')),
'note':ParagraphStyle('note',fontName='Arial',fontSize=10.5,leading=15.5,spaceAfter=12,textColor=colors.HexColor('#155E63')),
'small':ParagraphStyle('small',fontName='Arial',fontSize=8,leading=12,spaceAfter=8,textColor=colors.HexColor('#526768'))}
def page(n,title,sub,items):
 c.setFillColor(colors.HexColor('#155E63'));c.rect(0,H-8,W,8,fill=1,stroke=0)
 c.setFont('Arial',9);c.drawString(44,H-39,'yourday / PRIVACY POLICY')
 c.setFillColor(colors.HexColor('#203B3D'));c.setFont('Arial-Bold',24);c.drawString(44,H-82,title)
 c.setFillColor(colors.HexColor('#687D7E'));c.setFont('Arial',10);c.drawString(44,H-108,sub)
 if n==5:
  styles['body'].leading=14.5;styles['body'].spaceAfter=7
  styles['h'].spaceBefore=10;styles['h'].spaceAfter=7
 story=[Paragraph(escape(t).replace('\n','<br/>'),styles[k]) for k,t in items]
 Frame(44,60,W-88,H-190,leftPadding=0,rightPadding=0,topPadding=0,bottomPadding=0).addFromList(story,c)
 if story:raise RuntimeError(f'page {n} overflow {len(story)}')
 c.setStrokeColor(colors.HexColor('#D8E3E2'));c.line(44,45,W-44,45)
 c.setFillColor(colors.HexColor('#687D7E'));c.setFont('Arial',8);c.drawString(44,30,'Smile Dragon | Privacy inquiries: yonghk423423@gmail.com');c.drawRightString(W-44,30,f'{n} / 5');c.showPage()
page(1, 'Privacy Policy', 'yourday | Effective and last updated: October 28, 2026', [('body', 'Smile Dragon (the "Company," "we," "us," or "our") provides yourday. This Privacy Policy explains how personal information is processed for diary features, AI cartoon image conversion, connected services, and privacy inquiries. The privacy contact is Yonghee Kim, Representative, at yonghk423423@gmail.com.'), ('note', 'Photo processing at a glance: We do not separately store source photos or converted images on Company servers. We send the entire original photo you select to OpenAI to convert it into a cartoon image. External processing may also occur when content is checked for safety or blocked.'), ('h', '1. Information We Process and Why'), ('body', 'Diary features. Diary titles, character names, scenes, notes, tasks, and settings that you enter or select are processed on your device to create, view, edit, and manage your diary. We do not automatically synchronize this diary data to Company servers.'), ('body', 'AI cartoon conversion. We send the entire original photo you select and the necessary instructions to OpenAI to convert the photo into a cartoon image and return the result. People, faces, bodies, background details, and any other information visible in the original may be processed. We do not send your entire photo library.'), ('body', "Content safety. Input photos, conversion requests, and generated results may be checked automatically or processed by an external AI service's safety filters to restrict sexual or pornographic content, child sexual exploitation material, and other prohibited content."), ('body', 'Inquiries. We use your email address, message, and attachments you choose to send to respond to inquiries and privacy rights requests. Please avoid sending photos or sensitive information that is unnecessary to resolve your inquiry.'), ('h', '2. Selecting Photos and Your Choices'), ('body', 'Your photo is processed when you select it and request AI conversion. You may cancel before transmission or choose not to use the AI feature. If you do so, that photo cannot be converted. Only select photos you have a lawful right to use, including any necessary permission from other people depicted in them. You can manage photo access in your device settings; changing a permission does not recall information already transmitted. The child-photo restrictions in Section 12 also apply when another user submits the photo.')])
page(2, 'AI and Content Safety', 'OpenAI processing, prohibited content, and photo retention', [('h', '3. Processing Through OpenAI'), ('body', 'We use the OpenAI API to convert your selected photo into a cartoon image. The entire original photo and necessary conversion request are transmitted to OpenAI over a network, and we provide the returned result to you. If an external API is used for safety screening, a photo may be sent to OpenAI for screening even if its conversion is subsequently blocked. AI use and photo submissions must meet the eligibility requirements in Section 12.'), ('body', "We do not use your photos to train our own AI models or for advertising purposes you have not requested. We keep sharing of API inputs and outputs for OpenAI model training disabled. Under OpenAI's published API policy, API data is not used to train or improve its models by default unless the customer separately opts in to data sharing."), ('h', '4. Restrictions on Sexual and Illegal Content'), ('body', 'We do not permit conversion of sexually explicit or pornographic photos, creation or conversion of sexual images involving children or teenagers, non-consensual sexual images, or other unlawful content. When prohibited content is detected or OpenAI refuses a request under its safety policies, conversion may be stopped or delivery of the result restricted.'), ('body', "OpenAI's image service applies safety filters to inputs and generation. Where additional input or output screening is applied, a request or display of its result is blocked according to the screening outcome. Automated screening may miss inappropriate content or incorrectly block an ordinary photo. It does not guarantee that all inappropriate content will be blocked."), ('body', 'General sexual-content screening cannot reliably establish the age of a person in a photo or whether they are a minor. You can contact our privacy email about a blocked request and describe the issue without attaching the photo again.'), ('h', '5. Photo Storage and Deletion'), ('body', 'We do not separately retain source photos or converted images on Company servers. Photos and results saved on your device, and operating-system backups, are governed by your device and service settings. Our non-retention of photos does not mean that OpenAI or another external provider retains no data.'), ('body', 'OpenAI abuse-monitoring logs may contain request and response content and may be retained for up to 30 days by default. Exceptions may apply for legal obligations, safety review, or protection of the service or third parties. Additional storage conditions may depend on the API, features, and contract used.'), ('small', 'OpenAI data controls: https://developers.openai.com/api/docs/guides/your-data\nOpenAI under-18 guidance: https://developers.openai.com/api/docs/guides/safety-checks/under-18-api-guidance')])
page(3, 'Connected Services', 'Usage data, location, search requests, and service notices', [('h', '6. Usage Analytics and Error Diagnostics'), ('body', 'On iOS, Google Analytics for Firebase processes app-open and screen-view events, app-instance or installation identifiers, device details, operating-system and app versions, and related usage information to help us understand which screens are used most and country-level usage patterns. This collection is separate from the diary records stored on your device.'), ('body', 'Firebase Crashlytics processes crash reports, error messages, stack traces, installation identifiers, and device and app details to diagnose and resolve failures. Firebase states that crash data and associated identifiers are retained for 90 days before removal from live and backup systems begins. Analytics retention depends on the configured Google Analytics retention settings and applicable service policies.'), ('body', 'If Slack crash notifications are enabled, Slack receives an error type, app version, timestamp, and error details or stack trace so that we can investigate problems. Only this notification processing is conditional on the Slack integration being enabled.'), ('h', '7. Weather, Book Search, and Notices'), ('body', 'Weather. With your device location permission, the app obtains coordinates and sends latitude and longitude rounded to two decimal places to OpenWeather for current weather and the region name. Rounding reduces precision but does not make the location anonymous. You can deny or withdraw location permission in device settings; location-based weather will then be unavailable.'), ('body', 'Book search. Search terms and book identifiers are sent to Aladin or Open Library to retrieve search results and book details. Book cover requests may also be sent to the relevant image provider. Do not include private information in search terms.'), ('body', 'Notices. The app contacts a Supabase-hosted service to load announcements. These requests do not automatically synchronize your diary to that service. Providers receiving network requests can process connection information, such as an IP address, in addition to the data needed for the feature.'), ('body', 'These connected services are used for the purposes described above. Photo or location permission controls do not themselves disable Analytics or Crashlytics. For questions or requests about diagnostic or usage information, contact our privacy email. Deleting local app data does not automatically delete provider records.'), ('small', 'Provider information: firebase.google.com/support/privacy | slack.com/trust/privacy/privacy-policy\nopenweather.co.uk/privacy-policy | aladin.co.kr | openlibrary.org\nsupabase.com/privacy')])
page(4, 'Transfers and Data Management', 'International processing, deletion, and protection of information', [('h', '8. External Processing and International Transfers'), ('body', 'OpenAI processes photos and conversion requests for AI conversion and safety screening. Google/Firebase processes usage and diagnostic information. Other connected providers and the information they receive are described in Sections 6 and 7. Processing by a provider is separate from storing your diary on your device.'), ('body', 'The OpenAI project used for the service uses the Global region setting, so photos and related request information may be processed or stored outside your country. Global does not mean processing or storage occurs exclusively in the United States.'), ('body', 'Transfers occur over a network when you request the relevant AI or connected feature; usage and diagnostic transmissions may occur automatically when the relevant iOS services operate. You can decline an AI photo transfer by not requesting conversion or by cancelling before transmission. In that case the relevant conversion cannot be provided. A request already sent cannot be recalled by revoking a device permission.'), ('body', 'Where laws of the EEA, United Kingdom, or another jurisdiction apply, the relevant requirements for lawful processing and international transfers apply. You may contact our privacy email to ask about your information, external recipients, and applicable safeguards.'), ('h', '9. Retention and Deletion'), ('body', "Local diary records and settings remain until you delete them or reset app data. You can remove local app records using the app's reset-data control in Settings. That process removes the app's local stored records; it does not remove separately saved gallery images, operating-system backups, or records already held by providers. We cannot remotely restore or delete local records that we do not hold."), ('body', 'Source and converted photo retention is explained in Section 5. Inquiry messages and attachments are retained while the inquiry or a related dispute is being handled, and are deleted when that purpose ends unless a legal retention duty applies. Information required for an unresolved legal claim or a legal obligation is kept only for that purpose until the relevant requirement ends. External provider retention and deletion also depend on the service, API, settings, and applicable legal requirements.'), ('h', '10. Protection of Information'), ('body', "Connected API requests use HTTPS. The app stores diary records locally rather than automatically uploading them to a Company diary database. Device storage is subject to your device's access controls and backup settings. Use a device lock and review your backup settings. No electronic storage or transmission method can guarantee absolute security. To report a suspected privacy or security issue, contact our privacy email without attaching unnecessary sensitive information.")])
page(5, 'Your Rights and Contact', "Privacy requests, children's information, and policy changes", [('h', '11. Your Rights and Requests by Guardians'), ('body', "Depending on applicable law, you may request access, correction, deletion, suspension or restriction of processing, withdrawal of consent, objection, or data portability. We may verify your identity or an authorized representative's authority to the extent necessary. We respond under applicable legal procedures and time limits and explain if a request cannot be fulfilled."), ('body', 'Where processing is based on consent, you may withdraw that consent without affecting the lawfulness of processing before withdrawal. We handle requests concerning information held by external providers within our rights and authority under applicable contracts and law. We cannot guarantee immediate direct deletion of all records held by a provider.'), ('h', '12. Children and Teenagers'), ('body', "yourday's diary features are intended for users of all ages. AI photo conversion is subject to additional eligibility requirements and restrictions on children's personal information."), ('body', "Children who require a parent or legal guardian's consent under applicable law may use AI photo conversion only after that consent has been obtained and verified and the necessary safeguards are in place. Until these conditions are met, their AI use and submission of their photos for AI conversion are not permitted, including submission by another user."), ('body', 'Processing personal information of children under 13, or under the applicable age of digital consent, through OpenAI is not permitted unless Zero Data Retention has been approved and enabled for the API and features used, alongside applicable consent and safety requirements. Parental consent alone does not replace this requirement.'), ('body', "A parent or legal guardian may contact our privacy email to ask about a child's information, exercise applicable rights, withdraw consent, or request deletion. Withdrawal stops any further processing that depends on that consent."), ('h', '13. Privacy Contact and Complaints'), ('body', 'Operator: Smile Dragon\nPerson responsible for privacy: Yonghee Kim, Representative\nPrivacy inquiries and rights requests: yonghk423423@gmail.com'), ('body', 'In South Korea, you can contact the Personal Information Infringement Report Center (privacy.kisa.or.kr; 118 within South Korea) or the Personal Information Dispute Mediation Committee (kopico.go.kr). You also retain the right to complain to the relevant supervisory authority in your jurisdiction. This Policy does not restrict rights provided by mandatory applicable law.'), ('h', '14. Availability and Changes'), ('body', 'We make this Policy available through app settings or another accessible location. The date shown on the first page identifies the latest revision. If important information changes, including processing purposes, data categories, or external providers, we communicate the changes and when they apply through an appropriate channel. Where additional consent is legally required, we obtain it before the relevant processing.')])
c.save();print(OUT)
